#include "PluginEditor.h"
#include <cstring>
DISidechainEditor::DISidechainEditor(DISidechainProcessor& p):AudioProcessorEditor(&p),proc(p){const char* ids[]={"depth","mix","threshold","length","timeOffset","lookahead","attackProtection","retrigger","smooth","cutoff","resonance","filterDrive","filterMod","filterMix","colorDrive","colorMix","output"};for(auto id:ids){auto s=std::make_unique<juce::Slider>(juce::Slider::RotaryHorizontalVerticalDrag,juce::Slider::TextBoxBelow);s->setName(id);s->setRange(0,1,0.001);if(!strcmp(id,"timeOffset"))s->setRange(-1,1,.001);if(!strcmp(id,"threshold"))s->setRange(-60,0,.1);if(!strcmp(id,"length"))s->setRange(10,2000,1);if(!strcmp(id,"lookahead"))s->setRange(0,200,1);if(!strcmp(id,"retrigger"))s->setRange(1,250,1);if(!strcmp(id,"smooth"))s->setRange(.1,50,.1);if(!strcmp(id,"cutoff"))s->setRange(20,20000,1);if(!strcmp(id,"filterDrive")||!strcmp(id,"colorDrive"))s->setRange(0,24,.1);if(!strcmp(id,"output"))s->setRange(-24,12,.1);addAndMakeVisible(*s);sa.push_back(std::make_unique<juce::AudioProcessorValueTreeState::SliderAttachment>(p.state,id,*s));sliders.push_back(std::move(s));}for(auto spec:{std::pair<const char*,juce::StringArray>{"triggerMode",{"Audio","MIDI","Audio + MIDI"}},{"detector",{"Peak","RMS","Transient"}},{"division",{"1/16","1/8T","1/8","1/4T","1/4","1/2","1 bar"}},{"filterModel",{"LP12","LP24","LP48","HP12","HP24","HP48","Band Pass","Notch","Analog Ladder","SVF Morph","Comb","Formant/Vowel","Aggressive Bass"}},{"colorModel",{"Warm Saturation","Soft Clip","Hard Clip","Asymmetric Drive","Wavefold","Digital Crush"}}}){auto c=std::make_unique<juce::ComboBox>();c->addItemList(spec.second,1);addAndMakeVisible(*c);ca.push_back(std::make_unique<juce::AudioProcessorValueTreeState::ComboBoxAttachment>(p.state,spec.first,*c));combos.push_back(std::move(c));}{auto c=std::make_unique<juce::ComboBox>(); c->addItemList({"50%","75%","100%"},1); addAndMakeVisible(*c); ca.push_back(std::make_unique<juce::AudioProcessorValueTreeState::ComboBoxAttachment>(p.state,"uiScale",*c)); combos.push_back(std::move(c));} sync=std::make_unique<juce::ToggleButton>("BPM SYNC");addAndMakeVisible(*sync);syncA=std::make_unique<juce::AudioProcessorValueTreeState::ButtonAttachment>(p.state,"sync",*sync);setResizable(true,true);setResizeLimits(550,350,1650,1050);setSize(1100,700);startTimerHz(30);}
void DISidechainEditor::paint(juce::Graphics& g){g.fillAll(juce::Colour(0xff0b1220));g.setColour(juce::Colours::white);g.setFont(juce::FontOptions(24));g.drawText("PRECISION SIDECHAIN",20,15,500,35,juce::Justification::left);auto graph=getLocalBounds().reduced(20).withTop(60).withHeight(260);g.setColour(juce::Colour(0xff111d2c));g.fillRoundedRectangle(graph.toFloat(),8);juce::Path curve;curve.startNewSubPath((float)graph.getX(),(float)graph.getBottom());for(int i=0;i<=100;i++){float x=i/100.f;float y=1.f-x*x*(3.f-2.f*x);curve.lineTo(graph.getX()+x*graph.getWidth(),graph.getY()+y*graph.getHeight());}g.setColour(juce::Colour(0xffff8b18));g.strokePath(curve,juce::PathStrokeType(3));g.setColour(juce::Colour(0xff24def0));g.drawLine((float)graph.getX(),graph.getCentreY(),(float)graph.getRight(),graph.getCentreY(),1);g.setColour(juce::Colours::white);g.setFont(juce::FontOptions(13));g.drawText("FILTER RESPONSE",graph.getX(),graph.getBottom()-22,200,20,juce::Justification::left);}
void DISidechainEditor::resized(){if(!sync)return;auto area=getLocalBounds().reduced(20).withTop(340);int cols=6;int w=area.getWidth()/cols,h=110;for(size_t i=0;i<sliders.size();++i)sliders[i]->setBounds(area.getX()+(int)(i%cols)*w,area.getY()+(int)(i/cols)*h,w-8,h-8);int y=area.getBottom()-100;for(size_t i=0;i<combos.size();++i)combos[i]->setBounds(20+(int)i*200,y,185,28);sync->setBounds(900,y,150,28);}
